<?php
namespace Junior\Clientside; class Request { const JSON_RPC_VERSION = "2.0"; public $method; public $params; public $id; public function __construct($method, $params = null, $notify = false) { if ($params !== null && !is_array($params)) { $params = array($params); } if (substr($method, 0, 4) == 'rpc.') { throw new Exception("Illegal method name; Method cannot start with 'rpc.'"); } $this->method = $method; $this->params = $params; if ($notify == false) { $this->id = uniqid(); } } public function getArray() { $arr = array('jsonrpc' => self::JSON_RPC_VERSION, 'method' => $this->method); if ($this->params) { $arr['params'] = $this->params; } if ($this->id !== null) { $arr['id'] = $this->id; } return $arr; } public function getJSON() { return json_encode($this->getArray(), JSON_UNESCAPED_UNICODE); } } 